"""Original predictions, written before any experiment was run. No corpus input."""
import json
from pathlib import Path
root = Path(__file__).resolve().parent
cases = []
def case(title, prediction, commands):
    ident = f'{len(cases)+1:02d}'
    script = 'register lv3\n' + commands.strip() + '\n'
    cases.append(dict(id=ident, title=title, prediction=prediction, script=script))
case('A measured joule becomes warm water', '10 kJ into 100 g water should raise temperature roughly 24 K, without mass loss below boiling.', 'add v1 water 100g\nheat v1 10kJ\ninspect v1\nmeasure v1 thermometer\nmeasure v1 balance')
case('Undo a thermal pulse', 'Heating then removing the same 10 kJ should return 100 g water close to its initial temperature and mass.', 'add v1 water 100g\nheat v1 10kJ\ncool v1 10kJ\ninspect v1')
case('Mix unequal hot and cold portions', '75 g at 20 C plus 25 g at 80 C should equilibrate near 35 C; mass should be 100 g.', 'add v1 water 75g @ 20C\nadd v1 water 25g @ 80C\ninspect v1')
case('A double dose is not a double temperature rise', 'Equal 10 kJ pulses into 100 g and 200 g water should produce approximately 2:1 temperature rises.', 'add v1 water 100g\nnew\nadd v2 water 200g\nheat v1 10kJ\nheat v2 10kJ\ninspect')
case('Latent heat intercepts the cooling pulse', 'Removing 20 kJ from 100 g water initially at 5 C should give an ice/water mixture near 0 C, not liquid at -43 C.', 'add v1 water 100g @ 5C\ncool v1 20kJ\ninspect v1\nmeasure v1 ph')
case('Boiling spends energy on disappearing liquid', '40 kJ into 100 g water at 95 C should approach 100 C and evaporate roughly 17 g rather than heat all liquid to 190 C.', 'add v1 water 100g @ 95C\nheat v1 40kJ\ninspect v1\nmeasure v1 ph')
case('Salt versus sugar freezing race', 'At equal 0.02 mol doses in 100 g water, NaCl should depress freezing roughly twice as much as sucrose. Both should form ice after 15 kJ cooling from 5 C.', 'add v1 water 100g @ 5C\nadd v1 NaCl 0.02mol\nnew\nadd v2 water 100g @ 5C\nadd v2 C12H22O11 0.02mol\ncool v1 15kJ\ncool v2 15kJ\ninspect')
case('Heat dilution cannot invent energy', 'Mixing two equal water portions at 60 C should keep them near 60 C, not reset the second dose to room temperature.', 'add v1 water 50g @ 60C\nadd v1 water 50g @ 60C\ninspect v1')
case('A tenfold acid dilution', 'Diluting 0.001 mol HCl in 100 mL water with another 900 mL should raise pH by about one unit (roughly 2 to 3).', 'add v1 water 100mL\nadd v1 HCl 0.001mol\nmeasure v1 ph\ndilute v1 900mL\nmeasure v1 ph\ninspect v1')
case('Acid/base cancellation and overshoot', '0.001 mol HCl followed by equal NaOH should reach near-neutral pH; another 0.001 mol NaOH should make it alkaline.', 'add v1 water 100mL\nadd v1 HCl 0.001mol\nadd v1 NaOH 0.001mol\nmeasure v1 ph\nadd v1 NaOH 0.001mol\nmeasure v1 ph\ninspect v1')
case('Weak acid versus strong acid', 'Equal 0.001 mol doses in 100 mL should give acetic acid a higher pH than HCl, by at least one unit.', 'add v1 water 100mL\nadd v1 HCl 0.001mol\nnew\nadd v2 water 100mL\nadd v2 CH3COOH 0.001mol\nmeasure v1 ph\nmeasure v2 ph\ninspect')
case('Half-neutralisation exposes a pKa', '0.01 mol acetic acid and 0.005 mol NaOH in 100 mL should form a buffer around pH 4.5-5.0.', 'add v1 water 100mL\nadd v1 CH3COOH 0.01mol\nadd v1 NaOH 0.005mol\nmeasure v1 ph\ninspect v1')
case('A buffer survives a small acid pulse', 'A half-neutralised acetate buffer should change pH far less than plain water after the same 0.0001 mol HCl pulse.', 'add v1 water 100mL\nadd v1 CH3COOH 0.01mol\nadd v1 NaOH 0.005mol\nmeasure v1 ph\nnew\nadd v2 water 100mL\nmeasure v2 ph\nadd v1 HCl 0.0001mol\nadd v2 HCl 0.0001mol\nmeasure v1 ph\nmeasure v2 ph')
case('Neutral salt is an ionic conductor', 'Adding 0.001 mol NaCl to 100 mL water should increase conductivity substantially while leaving pH approximately neutral.', 'add v1 water 100mL\nmeasure v1 conductivity\nadd v1 NaCl 0.001mol\nmeasure v1 conductivity\nmeasure v1 ph')
case('Sugar is not an electrolyte', 'A 0.001 mol sucrose dose should not increase conductivity like an equal NaCl dose; any missing conductivity model should be explicit.', 'add v1 water 100mL\nadd v1 C12H22O11 0.001mol\nnew\nadd v2 water 100mL\nadd v2 NaCl 0.001mol\nmeasure v1 conductivity\nmeasure v2 conductivity')
case('Common ions make a silver cloud', '0.001 mol each of NaCl and AgNO3 in 100 mL should produce close to 0.001 mol solid AgCl, with conserved silver and chloride.', 'add v1 water 100mL\nadd v1 NaCl 0.001mol\nadd v1 AgNO3 0.001mol\ninspect v1')
case('Precipitation cannot depend on bottle order', 'Reversing the equal silver/chloride additions should leave essentially equal AgCl solid amounts and pH in the two vessels.', 'add v1 water 100mL\nadd v1 NaCl 0.001mol\nadd v1 AgNO3 0.001mol\nnew\nadd v2 water 100mL\nadd v2 AgNO3 0.001mol\nadd v2 NaCl 0.001mol\ninspect')
case('Remove the cloud without removing the salt water', 'Filtering an AgCl suspension should retain its solid in v1 and move aqueous material to v2; total inventory should be conserved.', 'add v1 water 100mL\nadd v1 NaCl 0.002mol\nadd v1 AgNO3 0.001mol\nnew\nfilter v1 v2\ninspect')
case('Barium and sulfate meet', 'Equal 0.001 mol BaCl2 and Na2SO4 in 100 mL should form very insoluble BaSO4, or explicitly identify unavailable chemistry.', 'add v1 water 100mL\nadd v1 BaCl2 0.001mol\nadd v1 Na2SO4 0.001mol\ninspect v1')
case('Chalk dissolves in acid', '0.001 mol CaCO3 should be consumed by 0.003 mol HCl in 100 mL; carbon dioxide should be accounted for and excess acid remain.', 'add v1 water 100mL\nadd v1 CaCO3 0.001mol\nadd v1 HCl 0.003mol\ninspect v1\nmeasure v1 ph')
case('Finite solvent leaves salt behind', '100 g NaCl in 100 g water should leave substantial undissolved solid instead of an unlimited solution.', 'add v1 water 100g\nadd v1 NaCl 100g\ninspect v1')
case('Extra solvent rescues leftover salt', 'Adding another 500 mL water to 50 g NaCl in 100 g water should dissolve the residual solid.', 'add v1 water 100g\nadd v1 NaCl 50g\ninspect v1\ndilute v1 500mL\ninspect v1')
case('Drying a dilute salt solution', 'Evaporating 90% of the solvent from 0.001 mol NaCl in 100 g water should conserve sodium/chloride while increasing concentration roughly tenfold.', 'add v1 water 100g\nadd v1 NaCl 0.001mol\nevaporate v1 0.9\ninspect v1\nmeasure v1 balance')
case('A quarter of a solution carries a quarter of its salt', 'Decanting fraction 0.25 should send about 25% of dissolved NaCl and water to v2 and conserve combined mass.', 'add v1 water 100g\nadd v1 NaCl 0.01mol\nnew\ndecant v1 v2 0.25\ninspect')
case('Splitting and reuniting a solution', 'Decant 0.4 into v2 then all of v2 back to v1 should restore initial inventory, temperature, and pH within numerical tolerance.', 'add v1 water 100g\nadd v1 NaCl 0.01mol\ninspect v1\nnew\ndecant v1 v2 0.4\ndecant v2 v1 1\ninspect')
case('A hot pack versus a cold pack', 'Dissolving 0.01 mol CaCl2 should warm 100 g water; dissolving 0.01 mol KNO3 should cool it, or name missing enthalpy data.', 'add v1 water 100g\nadd v1 CaCl2 0.01mol\nnew\nadd v2 water 100g\nadd v2 KNO3 0.01mol\ninspect')
case('CO2 changes water chemistry', 'Adding 0.001 mol CO2 to 100 mL water should acidify it; absorbed and released carbon should be distinguished.', 'add v1 water 100mL\nmeasure v1 ph\nadd v1 CO2 0.001mol\nmeasure v1 ph\ninspect v1')
case('A small sealed headspace makes fizz push back', 'Acidifying 0.001 mol NaHCO3 with 0.002 mol HCl over a sealed 10 mL headspace should raise pressure above ambient and retain carbon.', 'add v1 water 100mL\nseal v1 10mL\nadd v1 NaHCO3 0.001mol\nadd v1 HCl 0.002mol\nmeasure v1 pressure\ninspect v1')
case('Headspace size controls pressure', 'The same acid/carbonate doses should produce higher final pressure over 10 mL than 100 mL sealed headspace.', 'add v1 water 100mL\nseal v1 10mL\nadd v1 NaHCO3 0.001mol\nadd v1 HCl 0.002mol\nnew\nadd v2 water 100mL\nseal v2 100mL\nadd v2 NaHCO3 0.001mol\nadd v2 HCl 0.002mol\nmeasure v1 pressure\nmeasure v2 pressure\ninspect')
case('Uncorking releases the compressed gas', 'Opening an acid/carbonate vessel should restore ambient gas pressure and account for vented gas without losing sodium/chloride.', 'add v1 water 100mL\nseal v1 10mL\nadd v1 NaHCO3 0.001mol\nadd v1 HCl 0.002mol\nopen v1\nmeasure v1 pressure\ninspect v1')
case('Fixed pressure trades pressure rise for expansion', 'Acid/carbonate under 1 bar regulation should stay near 1 bar and increase gas volume or explicitly state the unsupported constraint.', 'add v1 water 100mL\nregulate v1 1bar 10mL\nadd v1 NaHCO3 0.001mol\nadd v1 HCl 0.002mol\nmeasure v1 pressure\ninspect v1')
case('Sweeping carbon dioxide out', 'A nitrogen sweep after a finite CO2 dose should lower retained carbon and raise pH relative to the carbonated state, with a gas-transfer account.', 'add v1 water 100mL\nseal v1 100mL\nadd v1 CO2 0.001mol\nmeasure v1 ph\nsweep v1 1bar\nwait 60s\nmeasure v1 ph\ninspect v1')
case('A sacrificial zinc strip plates copper', 'Zinc in 0.001 mol CuSO4 solution should produce copper metal and consume zinc; mass/inventory should show the exchange.', 'add v1 water 100mL\nadd v1 CuSO4 0.001mol\nadd v1 Zn 0.002mol\ninspect v1')
case('Copper refuses the reverse displacement', 'Copper in ZnSO4 should not plate zinc; an explicit no-reaction result should be chemically distinguished from missing chemistry.', 'add v1 water 100mL\nadd v1 ZnSO4 0.001mol\nadd v1 Cu 0.002mol\ninspect v1')
case('Acid dissolves zinc but leaves copper', 'Equal metal doses with dilute HCl should dissolve zinc and evolve H2, while copper remains under non-oxidising conditions.', 'add v1 water 100mL\nadd v1 HCl 0.004mol\nadd v1 Zn 0.001mol\nnew\nadd v2 water 100mL\nadd v2 HCl 0.004mol\nadd v2 Cu 0.001mol\ninspect')
case('A battery has a polarity', 'Zn/ZnSO4 and Cu/CuSO4 half-cells at similar concentration should give about 1.1 V; reversing cell arguments should reverse the sign.', 'add v1 water 100mL\nadd v1 ZnSO4 0.001mol\nadd v1 Zn 0.001mol\nnew\nadd v2 water 100mL\nadd v2 CuSO4 0.001mol\nadd v2 Cu 0.001mol\ncell v1 v2\ncell v2 v1')
case('A concentration cell vanishes at equality', 'Identical copper half-cells should give near-zero voltage; diluting one tenfold should produce a nonzero voltage of order tens of mV.', 'add v1 water 100mL\nadd v1 CuSO4 0.001mol\nadd v1 Cu 0.001mol\nnew\nadd v2 water 100mL\nadd v2 CuSO4 0.001mol\nadd v2 Cu 0.001mol\ncell v1 v2\ndilute v2 900mL\ncell v1 v2')
case('A measured charge liberates a measured amount', 'Electrolysing acidified water at 0.1 A for 100 s should account for about 5.18e-5 mol H2 and 2.59e-5 mol O2, or name electrode/product limitations.', 'add v1 water 100mL\nadd v1 H2SO4 0.001mol\nelectrolyse v1 0.1A 100s\ninspect v1')
case('Dilution lightens a coloured solution', 'Tenfold dilution of CuSO4 should lower optical absorbance and lighten colour; any unavailable spectrum should be named.', 'add v1 water 100mL\nadd v1 CuSO4 0.01mol\nlook v1\nmeasure v1 uvvis\ndilute v1 900mL\nlook v1\nmeasure v1 uvvis')
case('Purple colour follows concentration', 'Tenfold dilution of dilute KMnO4 should reduce absorbance and fade purple toward pink without losing permanganate inventory.', 'add v1 water 100mL\nadd v1 KMnO4 0.0001mol\nlook v1\nmeasure v1 uvvis\ndilute v1 900mL\nlook v1\nmeasure v1 uvvis\ninspect v1')
case('A salt flame is not fuel', 'Igniting NaCl should report a yellow sodium flame signature or a boundary, without consuming salt as combustible fuel.', 'add v1 NaCl 1g\nignite v1\ninspect v1')
case('Magnesium gains oxygen mass', 'Igniting 0.001 mol Mg should create MgO and gain about 0.016 g from atmospheric oxygen, with the external mass source explained.', 'add v1 Mg 0.001mol\nignite v1\ninspect v1\nmeasure v1 balance')
case('Ethanol burns instead of returning a false negative', 'Igniting 1 g ethanol should produce combustion products/heat or explicitly identify missing combustion modelling.', 'add v1 ethanol 1g\nignite v1\ninspect v1')
case('Distillation enriches a volatile component', 'Distilling 10% of an ethanol/water mixture should enrich ethanol in the receiver and conserve both components across vessels plus declared losses.', 'add v1 water 80g\nadd v1 ethanol 20g\nnew\ndistil v1 v2 0.1\ninspect')
case('Oil and water keep separate layers', 'Equal 50 mL doses of water and olive oil should form separate phases; unresolved oil should be explicitly conserved, not dissolved into imaginary aqueous species.', 'add v1 water 50mL\nadd v1 olive_oil 50mL\nlook v1\ninspect v1')
case('Draining the bottom layer', 'Draining a water/oil mixture should send its lower aqueous layer to v2 while retaining oil in v1 and conserving combined inventory.', 'add v1 water 50mL\nadd v1 olive_oil 50mL\nnew\ndrain v1 v2\ninspect')
case('Salt cannot pass through an oil layer as water', 'Salt added to water/oil should reside in the aqueous phase; the oil layer should not acquire aqueous conductivity or pH as if homogeneous.', 'add v1 water 50mL\nadd v1 olive_oil 50mL\nadd v1 NaCl 0.001mol\ninspect v1\nmeasure v1 ph\nmeasure v1 conductivity')
case('Acid curdles milk without inventing protein molecules', 'Acidifying milk should show aggregation/curdling or a clear protein-model boundary, and retain unresolved milk mass.', 'add v1 whole_milk 100g\nadd v1 CH3COOH 0.01mol\nlook v1\ninspect v1')
case('A peroxide catalyst has an explicit model boundary', 'MnO2 added to dilute hydrogen peroxide should yield oxygen and catalytic turnover or explicitly say kinetics/catalysis is unavailable; silence would fail.', 'add v1 water 100mL\nadd v1 H2O2 0.01mol\nadd v1 MnO2 0.001mol\nwait 60s\nlook v1\ninspect v1')
case('Waiting is not permission to teleport matter', 'Waiting one hour with dilute NaCl at room temperature should conserve dissolved salt and avoid spontaneous precipitation or chemical conversion; any evaporation must be accounted.', 'add v1 water 100g\nadd v1 NaCl 0.001mol\ninspect v1\nwait 1h\ninspect v1')
assert len(cases)==50
(root/'predictions.json').write_text(json.dumps(cases, indent=2)+'\n')
for c in cases:
    (root/'scripts'/f"{c['id']}.lab").write_text('# '+c['title']+'\n# Expectation: '+c['prediction']+'\n'+c['script'])
print(f'Frozen {len(cases)} predictions')
